<?php elseif($section==='claims'): ?><form class="panel community-form" method="post"><?= Security::field() ?><input type="hidden" name="action" value="claim-create"><h2>درخواست اتصال به پروفایل هنرمند</h2><?php $selected=(int)($old['artist_id']??0);UI::lookup('artist_id','هنرمند','artists',UI::artists($db,[$selected]),$selected); ?><label>مدرک یا توضیح ارتباط شما با هنرمند<textarea name="evidence" required maxlength="5000" rows="4"><?= e(UI::value($old??[],'evidence')) ?></textarea></label><p class="hint">نشانی نمونه‌کار یا راه معتبر بررسی مالکیت یا نمایندگی را بنویسید. اتصال تا بررسی مدیر فعال نمی‌شود. اگر پروفایل موجود نیست، نام هنرمند را هنگام ارسال اثر پیشنهاد دهید.</p><button class="primary">ثبت درخواست بررسی</button></form><div class="panel"><?php foreach($claims as $claim): ?><article><h3><?= e($claim['display_name']) ?> <span class="badge" data-status="<?= e($claim['status']) ?>"><?= e(UI::state($claim['status'])) ?></span></h3><p><?= e($claim['review_note']) ?></p><p class="hint"><?= e($claim['created_at']) ?></p></article><?php endforeach ?><?php if(!$claims): ?><p>درخواستی ثبت نشده است.</p><?php endif ?></div>
